using System.IO.Compression;
using System.Text.Json;
using System.Xml.Linq;
using Shixiang;
int passed=0;
void Check(bool condition,string message){if(!condition)throw new Exception(message);}
void Test(string name,Action action){action();Console.WriteLine("PASS "+name);passed++;}
var root=Path.Combine(Path.GetTempPath(),"shixiang-native-test-"+Guid.NewGuid());Directory.CreateDirectory(root);
try{
Test("defaults and status timestamps",()=>{var t=new TaskItem();Check(t.Status=="进行中"&&t.PeopleText=="王淞晖"&&t.Completed==""&&t.Due=="","defaults");t.Status="已完成";t.ApplyStatusTimestamp();Check(DateTimeOffset.TryParse(t.Completed,out _),"completion timestamp");t.Status="挂起";t.ApplyStatusTimestamp();Check(t.Completed=="","reopened completion must clear");});
Test("exact participant and inclusive date filters",()=>{var t=new TaskItem{PeopleText="王淞晖、李明，李明",Due="2026-11-02"};Check(t.People.Count==2,"deduplicate people");var f=new Dictionary<string,Filter>{{"people",new("李明")},{"due",new(From:new(2026,11,2),To:new(2026,11,2))}};Check(TaskFilter.Matches(t,AppData.BuiltIn,f,""),"combined filter");Check(t.PeopleText=="王淞晖、李明","full list retained");f["people"]=new("李");Check(!TaskFilter.Matches(t,AppData.BuiltIn,f,""),"exact match");f.Remove("people");t.Due="";Check(!TaskFilter.Matches(t,AppData.BuiltIn,f,""),"empty date excluded");});
Test("legacy JSON compatibility and file roundtrip",()=>{var dir=Path.Combine(root,"legacy");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"tasks.json"),"""
{"revision":7,"data":{"tasks":[{"id":"old-id","title":"旧版事项","created":"2026-11-02T01:00:00Z","due":"","completed":"2026-11-02T02:00:00Z","status":"已完成","people":["王淞晖","李明"],"progress":"**进展**","custom":{"custom_a":"测试"}}],"columns":[{"key":"custom_a","name":"项目","type":"text"}],"hidden":["created"],"mode":"collapsed"}}
""");using(var store=new FileStore(dir)){var t=store.State.Data.Tasks.Single();Check(t.Completed=="2026-11-02T02:00:00Z","preserve old completion time");Check(t.Id=="old-id"&&t["custom_a"]=="测试"&&store.State.Data.Mode=="collapsed","legacy fields");t.Title="修改后的事项";store.Save();Check(store.State.Revision==8,"revision");using var backup=JsonDocument.Parse(File.ReadAllText(store.FilePath+".bak"));Check(backup.RootElement.GetProperty("revision").GetInt32()==7,"previous backup");}
using(var restored=new FileStore(dir)){Check(restored.State.Data.Tasks[0].Title=="修改后的事项","restart restore");Check(restored.State.Data.Hidden.Contains("created"),"settings restore");}});
Test("exclusive file lock and corrupt-file preservation",()=>{var dir=Path.Combine(root,"locked");using(var s=new FileStore(dir)){bool failed=false;try{using var other=new FileStore(dir);}catch(IOException){failed=true;}Check(failed,"second writer rejected");}var path=Path.Combine(dir,"tasks.json");File.WriteAllText(path,"broken");try{using var ignored=new FileStore(dir);throw new Exception("corrupt file accepted");}catch(JsonException){}Check(File.ReadAllText(path)=="broken","original corrupt file unchanged");});
Test("custom fields, search and Excel workbook output",()=>{var t=new TaskItem{Title="=不是公式",PeopleText="王淞晖、李明",Progress="**进展**\n下一步"};t["custom_test"]="研发";var fields=AppData.BuiltIn.Concat(new[]{new Field("custom_test","项目","text")}).ToList();Check(TaskFilter.Matches(t,fields,new(),"研发"),"custom search");var file=Path.Combine(root,"tasks.xlsx");ExcelExport.Write(file,fields,new[]{t});if(Environment.GetEnvironmentVariable("TASK_TRACKER_TEST_XLSX") is string exportPath)File.Copy(file,exportPath,true);using var zip=ZipFile.OpenRead(file);Check(zip.GetEntry("[Content_Types].xml")!=null&&zip.GetEntry("xl/workbook.xml")!=null,"xlsx parts");using var sheet=zip.GetEntry("xl/worksheets/sheet1.xml")!.Open();var xml=XDocument.Load(sheet);XNamespace s="http://schemas.openxmlformats.org/spreadsheetml/2006/main";Check(xml.Descendants(s+"row").Count()==2,"one header and one task");var cells=xml.Descendants(s+"t").Select(e=>e.Value).ToList();Check(cells.Contains("王淞晖、李明")&&cells.Contains("**进展**\n下一步")&&cells.Contains("研发"),"full exported values");Check(!xml.Descendants(s+"f").Any(),"formula strings remain text");});
Console.WriteLine($"{passed} tests passed");
}finally{Directory.Delete(root,true);}
